package easy;public class DeleteNodeInBST{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static TreeNode deleteNode(TreeNode r,int k){if(r==null)return null;if(k<r.val)r.l=deleteNode(r.l,k);else if(k>r.val)r.r=deleteNode(r.r,k);else{if(r.l==null)return r.r;if(r.r==null)return r.l;TreeNode m=r.r;while(m.l!=null)m=m.l;r.val=m.val;r.r=deleteNode(r.r,m.val);}return r;}public static void main(String[]args){System.out.println("Delete works\n");}}
